parameters.jsCode:
// リード情報の整形
const lead = $input.first().json;
const aiSuggestion = $node['AI営業提案生成'].json.choices[0].message.content;
const successCases = $node['類似成功案件取得'].json;
const knowledgeData = $node['営業ナレッジDB検索'].json;

// 担当営業の判定
let assignedRep = 'general';
if (lead.NumberOfEmployees > 500) {
  assignedRep = 'enterprise-team';
} else if (lead.NumberOfEmployees > 100) {
  assignedRep = 'mid-market-team';
} else {
  assignedRep = 'smb-team';
}

// Slack メッセージの構築
const slackMessage = {
  channel: '#sales-leads',
  username: 'Salesforce Bot',
  icon_emoji: ':rocket:',
  text: `🎯 *新規リード通知* - <@${assignedRep}>`,
  attachments: [
    {
      color: 'good',
      title: '基本情報',
      fields: [
        { title: '会社名', value: lead.Company, short: true },
        { title: '業界', value: lead.Industry, short: true },
        { title: '担当者', value: `${lead.FirstName} ${lead.LastName}`, short: true },
        { title: '役職', value: lead.Title, short: true },
        { title: '従業員数', value: lead.NumberOfEmployees?.toString() || 'N/A', short: true },
        { title: 'リードソース', value: lead.LeadSource, short: true }
      ]
    },
    {
      color: '#36a64f',
      title: '📊 類似成功事例（成約率: ' + (successCases.length > 0 ? '75%' : 'N/A') + '）',
      text: successCases.slice(0, 3).map(c => 
        `• ${c.Name} - ¥${c.Amount?.toLocaleString() || 'N/A'}`
      ).join('\n') || 'データなし'
    },
    {
      color: '#3AA3E3',
      title: '🎯 AIによる推奨アプローチ',
      text: aiSuggestion,
      footer: 'Powered by GPT-4 + 営業ナレッジDB'
    },
    {
      color: 'warning',
      title: '⚠️ 注意点',
      text: knowledgeData?.[0]?.key_points || '初回アプローチは迅速に（24時間以内）'
    }
  ],
  blocks: [
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `*Salesforceリンク:* <https://your-instance.salesforce.com/lightning/r/Lead/${lead.Id}/view|リード詳細を開く>`
      }
    },
    {
      type: 'actions',
      elements: [
        {
          type: 'button',
          text: {
            type: 'plain_text',
            text: '担当者として設定'
          },
          style: 'primary',
          action_id: 'assign_lead',
          value: lead.Id
        },
        {
          type: 'button',
          text: {
            type: 'plain_text',
            text: 'タスク作成'
          },
          action_id: 'create_task',
          value: lead.Id
        }
      ]
    }
  ]
};

return {
  json: slackMessage
};
